<?php
require '_layout.php'; admin_start('Reports', 'reports');
$from = $_GET['from'] ?? date('Y-m-01'); $to = $_GET['to'] ?? date('Y-m-d'); $R = "o.status IN " . REV_STATUS . " AND DATE(o.created_at) BETWEEN ? AND ?";
$daily = rows("SELECT DATE(o.created_at) d, COUNT(*) n, SUM(o.total) s FROM orders o WHERE $R GROUP BY d ORDER BY d DESC", [$from, $to]);
$prod = rows("SELECT oi.name, SUM(oi.qty) q, SUM(oi.qty*oi.price) rev, SUM(oi.qty*(oi.price-oi.cost)) pr FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE $R GROUP BY oi.name ORDER BY rev DESC LIMIT 20", [$from, $to]);
$pay = rows("SELECT o.payment_method m, COUNT(*) n, SUM(o.total) s FROM orders o WHERE $R GROUP BY m", [$from, $to]);
$cat = rows("SELECT COALESCE(c.name_en,'Uncategorized') n, SUM(oi.qty*oi.price) s FROM order_items oi JOIN orders o ON o.id=oi.order_id LEFT JOIN products p ON p.id=oi.product_id LEFT JOIN categories c ON c.id=p.category_id WHERE $R GROUP BY n ORDER BY s DESC", [$from, $to]);
if (isset($_GET['csv'])) { ob_end_clean(); header('Content-Type: text/csv'); header('Content-Disposition: attachment; filename=sales-report.csv'); $f = fopen('php://output', 'w'); fputcsv($f, ['Product', 'Qty', 'Revenue', 'Profit']); foreach ($prod as $r) fputcsv($f, [$r['name'], $r['q'], $r['rev'], $r['pr']]); exit; }
echo '<form class="filt panel-h"><span>From</span><input type="date" name="from" value="' . e($from) . '"><span>To</span><input type="date" name="to" value="' . e($to) . '"><button class="abtn sm">Apply</button><a class="abtn sm ghost" href="?' . e(http_build_query(['from' => $from, 'to' => $to, 'csv' => 1])) . '">⬇ Export CSV</a><button type="button" class="abtn sm ghost" onclick="print()">🖨 Print</button></form>';
echo '<div class="grid2"><div class="panel"><h3>Daily Sales</h3><div class="table-wrap"><table class="atbl"><tr><th>Date</th><th>Orders</th><th>Revenue</th></tr>'; foreach ($daily as $r) echo '<tr><td>' . date('d M Y', strtotime($r['d'])) . '</td><td>' . $r['n'] . '</td><td>' . money($r['s']) . '</td></tr>'; if (!$daily) echo '<tr><td colspan="3" class="empty">No sales in range.</td></tr>'; echo '</table></div></div>';
echo '<div class="panel"><h3>Sales by Category</h3><table class="atbl">'; foreach ($cat as $r) echo '<tr><td>' . e($r['n']) . '</td><td class="r">' . money($r['s']) . '</td></tr>'; echo '</table><h3 style="margin-top:20px">Payment Methods</h3><table class="atbl">'; foreach ($pay as $r) echo '<tr><td>' . e(strtoupper($r['m'])) . '</td><td>' . $r['n'] . ' orders</td><td class="r">' . money($r['s']) . '</td></tr>'; echo '</table></div></div>';
echo '<div class="panel"><h3>Top Products</h3><div class="table-wrap"><table class="atbl"><tr><th>Product</th><th>Qty Sold</th><th>Revenue</th><th>Profit</th></tr>'; foreach ($prod as $r) echo '<tr><td>' . e($r['name']) . '</td><td>' . $r['q'] . '</td><td>' . money($r['rev']) . '</td><td>' . money($r['pr']) . '</td></tr>'; if (!$prod) echo '<tr><td colspan="4" class="empty">No data.</td></tr>'; echo '</table></div></div>';
admin_end();
